  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_path(stage_path(rels), stage + 1, size) : rels;
};
var rels_path = stages_path([{}], 0, -1);
var path = rels_path[0];

// component 0 bool
// component 1 bool
// component 2 bool
// component 3 bool
// component 4 bool
// component 5 bool
// component 6 bool
// component 7 bool
// component 8 bool
// component 9 bool
// component 10 bool
// component 11 bool
// component 12 bool
// component 13 bool
// component 14 bool
var model = function() {
  return [holds(path, [1, 2])(),
          holds(path, [1, 3])(),
          holds(path, [1, 4])(),
          holds(path, [1, 5])(),
          holds(path, [1, 6])(),
          holds(path, [1, 7])(),
          holds(path, [1, 8])(),
          holds(path, [1, 9])(),
          holds(path, [1, 10])(),
          holds(path, [1, 11])(),
          holds(path, [1, 12])(),
          holds(path, [1, 13])(),
          holds(path, [1, 14])(),
          holds(path, [1, 15])(),
          holds(path, [1, 16])()];
};
Infer({method: 'enumerate'}, model);

