var path = rels_path[0];

// component 0 bool
// component 1 bool
// component 2 bool
// component 3 bool
// component 4 bool
// component 5 bool
// component 6 bool
// component 7 bool
// component 8 bool
// component 9 bool
// component 10 bool
// component 11 bool
var model = function() {
